    // Precompute powers of k modulo MOD up to w
    val powK = LongArray(w + 1)
    powK[0] = 1
    for (i in 1..w) {
        powK[i] = (powK[i - 1] * k) % MOD
    }

    // Precompute powers of (k-1) modulo MOD up to w
    val powKMinus1 = LongArray(w + 1)
    powKMinus1[0] = 1
    for (i in 1..w) {
        powKMinus1[i] = (powKMinus1[i - 1] * (k - 1)) % MOD
    }

    // Precompute powers of k modulo MOD up to w for the term (k-1)*k^(w-1)
    val powKForTerm = LongArray(w + 1)
    powKForTerm[0] = 1
    for (i in 1..w) {
        powKForTerm[i] = (powKForTerm[i - 1] * k) % MOD
    }

    // Calculate the sum S = sum_{i=0}^{w-1} (k-1) * k^i
    var S = 0L
    for (i in 0 until w) {
        S = (S + (k - 1) * powK[i]) % MOD
    }

    // Calculate the term (k-1) * k^(w-1)
    val term = ((k - 1).toLong() * powKForTerm[w - 1]) % MOD

    // Calculate the result
