fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (k, w) = br.readLine().split(" ").map { it.toLong() }

    if (k == 1L) {
        if (w >= 2) {
            println(-1)
        } else {
            println(0)
        }
        return
    }

    if (w == 1L) {
        println(0)
        return
    }

    // For w >= 2 and k >= 2, the answer is finite.
    // The formula is derived from combinatorial analysis.
    // The number of valid strings is (k*(k-1)) * ( (k^(w-1) - 1) / (k-1) ) ) mod MOD
    // But since we need to compute this efficiently, we use modular exponentiation and inverse.

    // Compute k^ (w-1) mod MOD
    fun powMod(a: Long, b: Long, mod: Long): Long {
        var res = 1L
        var base = a % mod
        var exp = b
        while (exp > 0) {
            if (exp % 2 == 1L) {
                res = (res * base) % mod
            }
            base = (base * base) % mod
            exp /= 2
        }
        return res
    }

    val term1 = k * (k - 1) % MOD
    val numerator = (powMod(k, w - 1, MOD) - 1 + MOD) % MOD
    val denominator = (k - 1) % MOD

    // Compute modular inverse of denominator
    val invDenominator = powMod(denominator, MOD - 2, MOD)
    val term2 = numerator * invDenominator % MOD

    val ans = term1 * term2 % MOD
    println(ans)
