const val MOD = 1000000007

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (k, w) = br.readLine().split(" ").map { it.toLong() }

    if (w >= k) {
        println(-1)
        return
    }

    var ans = 0L
    for (i in 1..w) {
        ans = (ans + comb(k, i) * comb(k - 1, i - 1)) % MOD
    }
    println(ans)
}

fun comb(n: Long, k: Long): Long {
    if (k > n || k < 0) return 0
    var res = 1L
    for (i in 0 until k) {
        res = res * (n - i) % MOD
        res = res * modInv(i + 1) % MOD
    }
    return res
}

fun modInv(a: Long): Long {
    var a = a
    var b = MOD - 2
    var res = 1L
    while (b > 0) {
        if (b and 1L == 1L) res = res * a % MOD
        a = a * a % MOD
        b = b shr 1
    }
    return res
}
